'use client';

import React from 'react';
import Image from 'next/image';
import { getDefaultImageByCategory } from '@/utils/image-helpers';

interface OptimizedImageProps {
  src: string;
  alt: string;
  width?: number;
  height?: number;
  className?: string;
  priority?: boolean;
  categorySlug?: string;
  fill?: boolean;
  sizes?: string;
}

export default function OptimizedImage({
  src,
  alt,
  width = 400,
  height = 300,
  className = '',
  priority = false,
  categorySlug,
  fill = false,
  sizes = '(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw'
}: OptimizedImageProps) {
  
  // Fallback image if src is invalid
  const imageSrc = src || getDefaultImageByCategory(categorySlug);
  
  // Optimize alt text for SEO
  const optimizedAlt = alt || `Imagen de ${categorySlug || 'publicación'}`;

  if (fill) {
    return (
      <Image
        src={imageSrc}
        alt={optimizedAlt}
        fill
        className={`object-cover ${className}`}
        priority={priority}
        sizes={sizes}
        quality={85}
        placeholder="blur"
        blurDataURL="data:image/jpeg;base64,"
      />
    );
  }

  return (
    <Image
      src={imageSrc}
      alt={optimizedAlt}
      width={width}
      height={height}
      className={`object-cover ${className}`}
      priority={priority}
      quality={85}
      placeholder="blur"
      blurDataURL="data:image/jpeg;base64,"
    />
  );
} 